import fs from 'node:fs';
const rmOptions = {
    force: true,
    recursive: true,
    maxRetries: 10,
    retryDelay: 100,
};
export async function rm(path) {
    await fs.promises.rm(path, rmOptions);
}
export function rmSync(path) {
    fs.rmSync(path, rmOptions);
}